using Astrea.BattleActions;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "EnemyActionLogic_PlayerTarget", menuName = "Data/Battle/Logics/Enemy Action/Player Target")]
public class EnemyActionLogic_PlayerTarget : EnemyActionLogic
{
	[SerializeField]
	private GameObjectReference playerGameObject;

	public override void ActivateAction(BattleAction battleAction, int actionAmount, GameObject source)
	{
		base.ActivateAction(battleAction, actionAmount, source);
		if (actionAmount == EffectsValues.NO_VALUE)
		{
			battleAction.CastTarget(playerGameObject.value, source);
		}
		else
		{
			battleAction.CastTargetAmount(playerGameObject.value, actionAmount, source);
		}
	}
}
